    public static class JanAmosKomenský
    {
        private const string Source = "https://cs.wikiquote.org/wiki/Jan_Amos_Komensk%C3%BD";

        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = Source, Text = "Bez příkladů, pravidel a cvičení buď ničemu se nevyučuje a neučí, nebo ničemu dobře.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Boháči bez moudrosti – co jsou jiného než vepři v blátě ležící?", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Čemukoli vyučuješ, hleď aby jasná pravda byla.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Čím je člověk vzdělanější, lepší a ušlechtilejší, tím víc si váží přírody.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Činný život je v pravdě životem, zahálka hrob člověka za živa.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Člověk dokonale učený jest strom na kořenu vlastním stojící, svou vlastní vláhou se napájející, vždycky stále a čím dále tím silněji rostoucí, zelenající se, kvetoucí, ovoce nesoucí.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Člověk vycvičený rozumem a uměním, avšak bez mravnosti, podobá se zlaté pochvě, v níž se olověný meč chová.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Dobré knihy jsou vpravdě brusem rozumu, pilníkem soudnosti, balšámem očí, nálevkami moudrosti, zrcadlem cizích myšlení, oprávcem pak našich myšlenek vlastních.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Dobrý učitel, dobrý učeň, dobré učení mocně umění rozmnožuje.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "I při nejlepším předsevzetí chybiti se může.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Jak docela věrný to obraz osudu smrtelníků! Právě ti z nich, kteří nejvíce dychtí po bohatství, poctách nebo rozkoších nebo jiných věcech v životě žádoucích, nejvíce hladovějí a žízní, poněvadž v rozkoších a žádostech není nasycení: jedí, aby jedli, pijí, aby opět pili. Jako svrabovitý člověk se nikdy nepřestane škrábati, tak rozkošník nezná konce v rozkošnictví, ctižádostivec ve ctižádosti, boháč v hromadění bohatství, poněvadž každá žádostivost je nenasytná.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Jediná lakota jest počestná – lakota času.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Jediným učitelem hodným toho jména jest ten, který vzbuzuje ducha svobodného přemýšlení a vyvinuje cit osobní odpovědnosti.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Jen to chci nyní připomenouti: Nesmí se mluvit o pošetilosti, jestliže někdo důvěřuje v dobrou věc a spoléhaje na Boha chtěl by a měl by odvahu volati na celý svět a celé lidské pokolení, aby zmoudřelo.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Jestliže zajisté něco pohřešuje střídavého odpočinku, není trvanlivé; my pak chceme vtip cvičiti tak, aby mohl vytrvati; potřebí tedy mezi práci vložiti od práce upouštění a mezery přestávek.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Jitřní zdraví nevylučuje večerní nemoc.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "K vyšším uctivě, k sobě rovným přátelsky, k nižším vlídně, ke všem laskavě a upřímně se chovej.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Každá práce celého člověka vyhledává.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Komukoli prospěti můžeš, prospívej rád, možno-li celému světu. Sloužiti a prospívati je vlastnost povah vznešených.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Lidskému tělu občerstvování potřebí, a to procházením, probíháním, pracemi, hrami a jakýmkoli těla pohybováním a cvičením.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Nebuďme, prosím, tak leniví, abychom po jiných toliko vždy hleděli a za jinými zdaleka se plaziti chtěli! Nechť nás také v něčem jiní před sebou vidí!", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Nevěřte všemu, co se vám k věření předkládá.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Neznámému nejinak než pomocí něčeho známého učí se.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Odvykejte bojům, zkujte své meče v motyky a oštěpy své v srpy.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Pec zkušuje zlato a trápení člověka.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Pochlebování je falešný peníz, který udržuje v oběhu jen naše marnivost.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Poznání sebe sama je základem pravé moudrosti.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Především je třeba vytyčiti si vysoký cíl, vyhýbati se zahálce, nezoufati v nehodách a nikdy neklesati na mysli.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Při jednom setrvej dokud třeba!", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Světlo má moc zahnat tmu, ne naopak. Kdekoli totiž vzchází světlo, tam tma brzy buď řídne nebo mizí. A naopak tma nemá sil aby odstranila světlo.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Synu můj, uč se moudrým býti.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Škola bez kázně – mlýn bez vody.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Šťastný je člověk, kterého varuje cizí chyba.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Učení samo má býti milé a libé a nemá se jinak díti, než jako hra a kratochvíle.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Vpravdě bohatý jest ten, kdož na tom, co má, přestati umí.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Vše ať se děje přirozeně, násilí ať se vzdálí ze všeho, co se děje.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Vše na tomto světě se dá napravit jen jemným teplem lásky, poněvadž jinak je to nemožno.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Všeliké kvaltování toliko pro hovada dobré jest.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Všichni na jednom divadle velikého světa stojíme, a cokoliv se tu koná, všech se týče, celé lidské pokolení jest z jedné krve, jedna rodina, jeden dům.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Základem zdraví a štěstí je střídmost ve všem, v jídle, v pití i v jiných požitcích. To je tajemství dlouhověkosti.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Žel, že na konci života vidíme, jak málo jsme uskutečnili z těch dobrých věcí, které jsme v minulých letech hodlali vykonati. Proto nikdy dobré konání neodkládej na dobu pozdější.", Author = "Jan Amos Komenský" },
            new Quote { Id = Source, Text = "Právnictví? To, co bych chtěl anebo nechtěl, aby mi dělali druzí, budu sám druhým dělat nebo nedělat.", Author = "Jan Amos Komenský" },
        };
    }
